using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.XR;using UnityEngine.XR.Interaction.Toolkit.Interactables;using UnityEngine.XR.Interaction.Toolkit.Inputs.Readers;using LighthouseKeepers.WatchDemo;using LighthouseKeepers.Core;using LighthouseKeepers.Net;using LighthouseKeepers.Gameplay.Interaction;using LighthouseKeepers.Interaction;
public static class BeltPeerV3 {
 static WatchDemoController W=>UnityEngine.Object.FindAnyObjectByType<WatchDemoController>();
 static XRGrabInteractable Tool(string kind)=>kind=="wrench"?UnityEngine.Object.FindAnyObjectByType<WatchPipeRepair>().wrench:kind=="radio"?UnityEngine.Object.FindObjectsByType<HandheldCrewRadio>(FindObjectsSortMode.None).OrderBy(r=>r.name).First().GetComponent<XRGrabInteractable>():W.Lantern(0).Grab;
 static HandRig Hand=>UnityEngine.Object.FindObjectsByType<HandRig>(FindObjectsInactive.Include,FindObjectsSortMode.None).First(h=>h.Node==XRNode.RightHand);
 public static object Prepare(string kind){EditorUtility.audioMasterMute=true;var rig=UnityEngine.Object.FindAnyObjectByType<Unity.XR.CoreUtils.XROrigin>();foreach(var m in rig.GetComponentsInChildren<UnityEngine.XR.Interaction.Toolkit.Inputs.XRInputModalityManager>(true))m.enabled=false;foreach(var b in rig.GetComponentsInChildren<Behaviour>(true))if(b.GetType().Name=="GravityProvider"||b.GetType().Name=="GroundedSlopeMovement")b.enabled=false;W.GetComponent<IslandSafety>().enabled=false;
 var g=Tool(kind);rig.MoveCameraToWorldLocation(g.transform.position+Vector3.up*.5f-Vector3.forward*.45f);var h=Hand;h.transform.parent.gameObject.SetActive(true);foreach(var t in h.transform.parent.GetComponents<UnityEngine.InputSystem.XR.TrackedPoseDriver>())t.enabled=false;h.enabled=false;h.transform.parent.SetPositionAndRotation(g.transform.position,Quaternion.identity);h.Direct.enabled=true;h.Direct.selectInput=new XRInputButtonReader("test grip",inputSourceMode:XRInputButtonReader.InputSourceMode.ManualValue);h.Direct.selectInput.QueueManualState(false,0);Physics.SyncTransforms();return true;}
 public static object Press(){Hand.Direct.selectInput.QueueManualState(true,1);return true;}
 public static object Slot(string kind){var g=Tool(kind);var head=W.GetComponent<KeeperToolBelt>().Head;Hand.transform.parent.position+=ToolBeltPose.Position(g.GetComponent<INetworkBeltSlot>().BeltSlot,head.position,head.rotation)-g.transform.position;return true;}
 public static object Release(){Hand.Direct.selectInput.QueueManualState(false,0);return true;}
 public static object Regrip(string kind){Hand.transform.parent.position=Tool(kind).transform.position;Physics.SyncTransforms();return true;}
 public static object Away(){Hand.transform.parent.position=W.GetComponent<KeeperToolBelt>().Head.position+Vector3.forward*.7f;return true;}
 public static object Facts(string kind){var g=Tool(kind);var b=g.GetComponent<FusionGrabBinding>();return new {g.name,g.isSelected,local=g.GetComponent<INetworkPropCarry>().Carried,b.IsCarried,b.Owner,b.Epoch,position=g.transform.position.ToString("F3"),binding=b.Id,wrenchActive=W.State.Coop.RemoteHeld(g)};}
}
